use vstd::prelude::*;

verus! {

    // Specification for counting the number of true values in a boolean array
    spec fn count_true_spec(arr: &Vec<bool>) -> nat
        requires
            arr.len() <= u64::MAX as usize, // Ensure the length of the array fits within u64
    {
        let mut count = 0;
        for i in 0..arr.len() {
            if arr[i] {
                count += 1;
            }
        }
        count as nat
    }

    fn count_true(arr: &Vec<bool>) -> (count: u64)
        requires
            arr.len() <= u64::MAX as usize, // Ensure the length of the array fits within u64
        ensures
            count <= arr.len() as u64, // The count must be between 0 and the length of the array
            count == count_true_spec(arr), // The count must equal the formal count
    {
        let mut count: u64 = 0;
        let mut idx: usize = 0;
        let len = arr.len();

        while idx < len
            invariant
                idx <= len,
                count <= idx as u64, // Count should not exceed the current index
                count == count_true_spec(&arr[..idx]), // Count matches the specification for the current slice
            decreases len - idx,
        {
            if arr[idx] {
                count = count + 1;
            }
            idx = idx + 1;
        }
        count
    }
}

